//! K3b — the differential corpus: OCCT's own section curves must lie
//! exactly on our closed-form intersections.
//!
//! The corpus (`tests/fixtures/k3_sections.json`) was generated by
//! `scripts/parity/regen_k3_sections.py` through the same pinned
//! FreeCAD 1.0.0 AppImage (r39109) the parity gate uses: for every
//! canonical analytic pair, OCCT's `BRepAlgoAPI_Section` edges
//! (trimmed to the sections' interiors — cap/rim edges dropped) are
//! recorded with their curve parameters and 33 sample points from
//! OCCT's own edge parameterization.
//!
//! The differential here is one-directional coverage, honestly: the
//! Rust engine intersects the **infinite** analytic surfaces while
//! OCCT intersected generous **finite** primitives, so our answer is
//! a superset (the double cone's mirror nappe, sections beyond the
//! frustum). The contract: every OCCT sample point lies within
//! machine-scale distance of some curve we return — if our closed
//! forms were wrong by even a hair, OCCT's own points would fall off
//! them.

use fc_base::Vector3;
use fc_part::intersect::{intersect_surfaces, SurfaceIntersection};
use fc_part::topology::{Curve, Surface};

fn v3(x: f64, y: f64, z: f64) -> Vector3 {
    Vector3::new(x, y, z)
}

fn vec_from_json(v: &serde_json::Value) -> Vector3 {
    let a = v.as_array().expect("vector as [x, y, z]");
    v3(
        a[0].as_f64().expect("x"),
        a[1].as_f64().expect("y"),
        a[2].as_f64().expect("z"),
    )
}

fn surface_from_json(o: &serde_json::Value) -> Surface {
    let kind = o["kind"].as_str().expect("operand kind");
    let any_perp = |axis: Vector3| {
        let probe = if axis.x.abs() < 0.9 {
            v3(1.0, 0.0, 0.0)
        } else {
            v3(0.0, 1.0, 0.0)
        };
        let d = probe.dot(&axis);
        (probe - axis * d)
            .normalized()
            .expect("axis is a direction")
    };
    match kind {
        "Plane" => Surface::Plane {
            origin: vec_from_json(&o["origin"]),
            normal: vec_from_json(&o["normal"]),
            x_dir: any_perp(vec_from_json(&o["normal"])),
        },
        "Sphere" => Surface::Sphere {
            center: vec_from_json(&o["center"]),
            axis: v3(0.0, 0.0, 1.0),
            ref_dir: v3(1.0, 0.0, 0.0),
            radius: o["radius"].as_f64().expect("radius"),
        },
        "Cylinder" => {
            let axis = vec_from_json(&o["axis"]);
            Surface::Cylinder {
                origin: vec_from_json(&o["origin"]),
                ref_dir: any_perp(axis),
                axis,
                radius: o["radius"].as_f64().expect("radius"),
            }
        }
        "Cone" => {
            let axis = vec_from_json(&o["axis"]);
            Surface::Cone {
                origin: vec_from_json(&o["origin"]),
                ref_dir: any_perp(axis),
                axis,
                semi_angle: o["semi_angle"].as_f64().expect("semi_angle"),
                ref_radius: o["ref_radius"].as_f64().expect("ref_radius"),
            }
        }
        "Torus" => {
            let axis = vec_from_json(&o["axis"]);
            Surface::Torus {
                center: vec_from_json(&o["center"]),
                ref_dir: any_perp(axis),
                axis,
                major_radius: o["major_radius"].as_f64().expect("major"),
                minor_radius: o["minor_radius"].as_f64().expect("minor"),
            }
        }
        other => panic!("unknown operand kind {other}"),
    }
}

/// The distance from `p` to the curve, machine-exactly for lines and
/// circles, coarse-plus-bisection-refined for ellipses (the sample
/// points' nearest-ellipse-point problem has no closed form).
fn distance_to_curve(curve: &Curve, p: Vector3) -> f64 {
    match curve {
        Curve::Line { origin, direction } => {
            let d = v3(p.x - origin.x, p.y - origin.y, p.z - origin.z);
            let cross = d.cross(direction);
            cross.length()
        }
        Curve::Circle {
            center,
            axis,
            radius,
            ..
        } => {
            let q = v3(p.x - center.x, p.y - center.y, p.z - center.z);
            let off = q.dot(axis);
            let radial = q - v3(axis.x * off, axis.y * off, axis.z * off);
            let radial_len = radial.length();
            if radial_len == 0.0 {
                // On the axis: every circle point is at radius.
                return *radius;
            }
            ((radial_len - radius) * (radial_len - radius) + off * off).sqrt()
        }
        Curve::Ellipse {
            center,
            axis,
            major_dir,
            major_radius,
            minor_radius,
        } => {
            let minor_dir = axis.cross(major_dir);
            let at = |t: f64| -> Vector3 {
                let (s, c) = t.sin_cos();
                v3(
                    center.x + major_radius * c * major_dir.x + minor_radius * s * minor_dir.x,
                    center.y + major_radius * c * major_dir.y + minor_radius * s * minor_dir.y,
                    center.z + major_radius * c * major_dir.z + minor_radius * s * minor_dir.z,
                )
            };
            // Coarse scan, then bisection on the squared-distance
            // derivative around the best bracket (g is unimodal in a
            // half-period window around any local minimum).
            let mut best_t = 0.0;
            let mut best_d2 = f64::INFINITY;
            let n = 4096;
            for i in 0..n {
                let t = i as f64 * (std::f64::consts::TAU / n as f64);
                let d = at(t);
                let d2 = (d.x - p.x) * (d.x - p.x)
                    + (d.y - p.y) * (d.y - p.y)
                    + (d.z - p.z) * (d.z - p.z);
                if d2 < best_d2 {
                    best_d2 = d2;
                    best_t = t;
                }
            }
            let dt = std::f64::consts::TAU / n as f64;
            let mut lo = best_t - dt;
            let mut hi = best_t + dt;
            let dist2 = |t: f64| {
                let d = at(t);
                (d.x - p.x) * (d.x - p.x) + (d.y - p.y) * (d.y - p.y) + (d.z - p.z) * (d.z - p.z)
            };
            for _ in 0..60 {
                let mid = 0.5 * (lo + hi);
                // local quadratic-ish: keep the better half
                if dist2(mid - 1e-12) < dist2(mid + 1e-12) {
                    hi = mid;
                } else {
                    lo = mid;
                }
            }
            dist2(0.5 * (lo + hi)).sqrt()
        }
        Curve::Bspline { .. } => f64::INFINITY,
    }
}

fn distance_to_curves(curves: &[Curve], p: Vector3) -> f64 {
    curves
        .iter()
        .map(|c| distance_to_curve(c, p))
        .fold(f64::INFINITY, f64::min)
}

#[test]
fn occt_section_samples_lie_on_our_closed_form_curves() {
    let path = std::env::var("FC_K3_CORPUS").unwrap_or_else(|_| {
        format!(
            "{}/tests/fixtures/k3_sections.json",
            env!("CARGO_MANIFEST_DIR")
        )
    });
    let bytes = match std::fs::read(&path) {
        Ok(b) => b,
        Err(e) => panic!(
            "K3 differential corpus not found at {path}: {e} \
             (regenerate with scripts/parity/regen_k3_sections.py \
             through the pinned FreeCAD 1.0.0 AppImage)"
        ),
    };
    let corpus: serde_json::Value = serde_json::from_slice(&bytes).expect("valid corpus JSON");
    let cases = corpus["cases"].as_array().expect("cases array");
    assert!(!cases.is_empty(), "the corpus must not be empty");

    let mut checked_points = 0usize;
    let mut checked_curves = 0usize;
    for case in cases {
        let name = case["name"].as_str().expect("case name");
        let a = surface_from_json(&case["a"]);
        let b = surface_from_json(&case["b"]);
        let ours = intersect_surfaces(&a, &b);
        let curves = match &ours {
            SurfaceIntersection::Curves(cs) => cs.clone(),
            other => panic!("case {name}: expected intersection curves, got {other:?}"),
        };
        assert!(
            !curves.is_empty(),
            "case {name}: every corpus case is a secant"
        );
        for cve in case["curves"].as_array().expect("curves array") {
            checked_curves += 1;
            let kind = cve["kind"].as_str().expect("curve kind");
            assert!(
                matches!(kind, "Line" | "Circle" | "Ellipse"),
                "case {name}: corpus carries an unexpected curve kind {kind}"
            );
            for s in cve["samples"].as_array().expect("samples") {
                let p = vec_from_json(s);
                let d = distance_to_curves(&curves, p);
                let tolerance = 1e-9 * (1.0 + p.length());
                assert!(
                    d <= tolerance,
                    "case {name}: OCCT {kind} sample {p:?} is {d:.3e} from \
                     every closed-form curve (tolerance {tolerance:.3e}) — \
                     the reference engine disagrees with the construction"
                );
                checked_points += 1;
            }
        }
    }
    println!(
        "K3 differential: {} OCCT curves, {} sample points, all covered",
        checked_curves, checked_points
    );
}

#[test]
fn our_curve_count_is_at_least_occts() {
    // The Rust engine intersects the infinite surfaces; OCCT saw
    // finite primitives — our answer must be a superset, never fewer.
    let path = std::env::var("FC_K3_CORPUS").unwrap_or_else(|_| {
        format!(
            "{}/tests/fixtures/k3_sections.json",
            env!("CARGO_MANIFEST_DIR")
        )
    });
    let bytes = std::fs::read(&path).expect("K3 corpus committed in-tree");
    let corpus: serde_json::Value = serde_json::from_slice(&bytes).expect("valid corpus JSON");
    for case in corpus["cases"].as_array().expect("cases array") {
        let name = case["name"].as_str().expect("case name");
        let a = surface_from_json(&case["a"]);
        let b = surface_from_json(&case["b"]);
        let occt_count = case["curves"].as_array().expect("curves").len();
        // OCCT splits closed sections into two edges; compare against
        // the rounded-up half count of ours via a generous bound: ours
        // must have at least ceil(occt/2) curves.
        let ours = match intersect_surfaces(&a, &b) {
            SurfaceIntersection::Curves(cs) => cs.len(),
            other => panic!("case {name}: expected curves, got {other:?}"),
        };
        assert!(
            ours >= occt_count.div_ceil(2),
            "case {name}: we returned {ours} curves vs OCCT's {occt_count} \
             edges (split sections count double) — a subset answer means \
             a missing branch"
        );
    }
}
